import{z as i,x as s,o as B,c as d,q as l,j as r,D as e,d as o,s as n,S as t,b as a}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"布雷顿森林与崩溃","description":"","frontmatter":{"title":"布雷顿森林与崩溃","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bretton-woods-collapse.md","filePath":"econ/bretton-woods-collapse.md","lastUpdated":1791413859000}'),p={name:"econ/bretton-woods-collapse.md"};function D(m,E,f,h,u,T){const A=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=l('<h1 id="布雷顿森林与崩溃" tabindex="-1">布雷顿森林与崩溃 <a class="header-anchor" href="#布雷顿森林与崩溃" aria-label="Permalink to &quot;布雷顿森林与崩溃&quot;">​</a></h1><div class="epigraph"><p>美元钉黄金、他国钉美元，把金本位的枷锁改写成金汇兑。特里芬困境是：世界要美元流动性，美国就必须赤字；赤字一久，黄金兑换承诺就不可信。</p><footer>—— Triffin, Gold and the Dollar Crisis, 1960；Eichengreen, Globalizing Capital 与 Bretton Woods 研究；Bordo 布雷顿森林史学；对照上一课金本位</footer></div><p><a href="/econ/gold-standard-depression">上一课</a>用金平价解释通缩如何全球同步。本课缺口是战后重建：不再让各国直接钉金，而让美元居中。固定汇率加资本管制，换来一段时间的贸易扩张与政策空间。崩溃不是「某年某月的会议失败」，而是兑换承诺与美元供给之间的不一致被资本流动揭开。后课滞胀把崩溃后的浮动接到石油与预期。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设计：美元 35 美元兑一盎司黄金，其他货币钉美元，可调平价，IMF 提供短期融资，资本账户未完全开放。相对经典金本位，国内 \\(M\\) 有一层缓冲，但仍要保卫美元平价。特里芬：世界储备需求增长快于美国黄金，只能靠美国对外负债提供美元；负债累积则兑换不可信。1960 年代美元过剩、黄金外流、黄金池与双价，都是同一承诺的裂缝。1971 关闭黄金窗口、1973 主要货币浮动，是裂缝走到头。缺口不是背史密森协议条款，而是：<strong>金汇兑把金约束集中在一个中心国；中心国的财政与经常账户一旦与兑换冲突，外围只能选升值、管制或脱钩。</strong></p><h3 id="布雷顿森林不是固定汇率的黄金时代" tabindex="-1">布雷顿森林不是固定汇率的黄金时代 <a class="header-anchor" href="#布雷顿森林不是固定汇率的黄金时代" aria-label="Permalink to &quot;布雷顿森林不是固定汇率的黄金时代&quot;">​</a></h3><p>资本管制压住三角的一角，才让固定汇率与国内目标短暂共存。把这段读成「固定汇率天生稳定」，会漏掉管制与美国黄金库存。可调平价在政治上很少及时下调，于是危机以不连续跳平价或脱钩出现，而不是平滑调整。与金本位对照：那里是多中心金约束；这里是单中心美元约束。通缩输出换成了通胀输出的种子——下一课滞胀。</p><p><span class="marginnote">Eichengreen 把布雷顿森林放进长期资本全球化：管制使系统可运转，金融开放使特里芬提前到期。Bordo 区分可调整钉住的理论与实际僵硬。</span></p><p><span class="marginnote">术语翻译：金汇兑本位就是「间接金本位」——你的货币不直接换黄金，先换美元，美元再按 35 美元一盎司换黄金。链条多一环，全球结算方便一层，但约束也分散到了「大家对美元的信心」这个新环节上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>机制对照三句。(1) 与金本位：仍是固定平价，但黄金只约束美元。(2) 特里芬：流动性 vs 信心不可兼得。(3) 资本账户逐步开放后，信心问题变成可交易的（黄金市场、远期）。政策实验：关闭黄金窗口后，美元贬值、石油以美元计价的价格冲击接踵而至——时序相关，因果要下一课的供给冲击与货币政策一起读。官方互换与双边黄金保证是同一承诺的补丁，补丁用尽才关闭窗口。</p>',11)),(B(),r(t,null,{default:e(()=>[n(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOLD%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E5%A4%9A%E5%9B%BD%E9%92%89%E9%87%91%22%5D%20--%3E%20BW%5B%22%E7%BE%8E%E5%85%83%E9%92%89%E9%87%91%2C%20%E4%BB%96%E5%9B%BD%E9%92%89%E7%BE%8E%E5%85%83%22%5D%0A%20%20BW%20--%3E%20TRI%5B%22%E7%89%B9%E9%87%8C%E8%8A%AC%3A%20%E6%B5%81%E5%8A%A8%E6%80%A7%E5%AF%B9%E4%BF%A1%E5%BF%83%22%5D%0A%20%20TRI%20--%3E%20CLOSE%5B%22%E5%85%B3%E9%97%AD%E9%BB%84%E9%87%91%E7%AA%97%E5%8F%A3%22%5D%0A%20%20CLOSE%20--%3E%20FLOAT%5B%22%E4%B8%BB%E8%A6%81%E8%B4%A7%E5%B8%81%E6%B5%AE%E5%8A%A8%22%5D%0A%20%20FLOAT%20--%3E%20STAG%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E6%BB%9E%E8%83%80%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"不要把 IMF 份额谈判当崩溃原因；融资是缓冲，承诺不一致才是核。可调平价若真按基本面及时调整，特里芬仍在——中心黄金库存赶不上美元负债——但危机会以一连串小贬值出现，而不是 1971 的硬关闭。政治上的平价僵硬把裂缝攒成一次断裂。补丁耗尽才关闭窗口，不是会议突然失败。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[o("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"机制是中心国资产负债表。世界要安全的美元资产，美国就必须做净负债国；同时承诺按固定价兑黄金，等于空头黄金。资本管制延长空头的寿命；欧洲美元市场与私人资本把它缩短。一旦私人不再相信 35 美元平价，官方黄金池也无法无限做市。浮动后，三角回到「独立 \\(M\\) + 资本流动」，汇率吸收冲击——但独立 \\(M\\) 立刻面对如何定锚，下一课是大通胀。",-1)),E[6]||(E[6]=a("p",null,"与主权可持续对照：美国当时的「债」包括对外美元负债加黄金兑换期权。阈值同样不是某一个黄金库存吨数，而是承诺是否还被相信。资本管制是推迟到期的工具，不是取消特里芬：欧洲美元市场一旦做大，私人可以绕开官方渠道给承诺定价，官方黄金池的做市深度就显得不够。",-1)),E[7]||(E[7]=a("p",null,[a("span",{class:"marginnote"},"Triffin 1960 的诊断先于崩溃十年。事后看，他抓对了流动性–信心冲突，没有预测具体月日——史课要机制，不要神谕。")],-1)),E[8]||(E[8]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：特里芬困境像一家承诺「随时按固定价兑黄金」的银行，而世界又要求它不断多发钞票满足取用——发得越多，越没人信它兑得起；不发，全球又缺流动性。两头堵，且随时间自动收紧。")],-1)),(B(),r(t,null,{default:e(()=>[n(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEM%5B%22%E4%B8%96%E7%95%8C%E7%BB%8F%E6%B5%8E%E6%89%A9%E5%BC%A0%2C%20%E5%82%A8%E5%A4%87%E9%9C%80%E6%B1%82%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20DEF%5B%22%E7%BE%8E%E5%9B%BD%E5%8F%AA%E8%83%BD%E9%9D%A0%E5%AF%B9%E5%A4%96%E8%B5%A4%E5%AD%97%E8%BE%93%E5%87%BA%E7%BE%8E%E5%85%83%22%5D%0A%20%20DEF%20--%3E%20LIQ%5B%22%E5%85%A8%E7%90%83%E6%B5%81%E5%8A%A8%E6%80%A7%E5%BE%97%E4%BB%A5%E6%BB%A1%E8%B6%B3%22%5D%0A%20%20DEF%20--%3E%20GAP%5B%22%E7%BE%8E%E5%85%83%E8%B4%9F%E5%80%BA%E7%9B%B8%E5%AF%B9%E9%BB%84%E9%87%91%E5%BA%93%E5%AD%98%E8%B6%8A%E6%BB%9A%E8%B6%8A%E5%A4%A7%22%5D%0A%20%20GAP%20--%3E%20DOUBT%5B%2235%20%E7%BE%8E%E5%85%83%E5%85%91%E6%8D%A2%E6%89%BF%E8%AF%BA%E5%8F%AF%E4%BF%A1%E5%BA%A6%E4%B8%8B%E9%99%8D%22%5D%0A%20%20DOUBT%20--%3E%20RUN%5B%22%E7%A7%81%E4%BA%BA%E6%8A%A2%E5%85%91%E9%BB%84%E9%87%91%2C%20%E5%BA%93%E5%AD%98%E5%8A%A0%E9%80%9F%E5%A4%96%E6%B5%81%22%5D%0A%20%20RUN%20--%3E%20GAP%0A%20%20DOUBT%20--%3E%20CLOSE%5B%221971%20%E5%85%B3%E9%97%AD%E9%BB%84%E9%87%91%E7%AA%97%E5%8F%A3%2C%20%E8%BD%AC%E5%90%91%E6%B5%AE%E5%8A%A8%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[9]||(E[9]=l('<p>这张图回答的是：特里芬为什么是「困境」而非「时间表」。注意中间的自环——负债越大越引发抢兑，抢兑又反过来放大负债与库存的缺口；信心问题一旦变成可交易的（黄金市场与远期），补丁（黄金池、双价制）就只能在深度上续命，不能取消算术。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写外汇交易执行，不进限价簿，不把每次高峰会列成年表。石油、工会、菲利普斯曲线预期转到下一课。后课默认：布雷顿森林是金汇兑加管制的折中；它的崩溃是特里芬承诺失败，不是「固定汇率理念失败」的抽象课。金本位的通缩枷锁与布雷顿的信心枷锁，是同一金属的两种松紧。SDR 与替代账户是事后补丁，改的是储备形态，没有取消中心国兑换承诺的算术。</p><p><span class="marginnote">数字实例：1950 年代初美国官方黄金库存约 2 万吨、占全球官方储备大半；到 1971 年关闭黄金窗口前已不足 9 千吨。所谓「承诺可信度」，落到账面上就是这条库存曲线的斜率。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>金汇兑把金约束集中到美元兑换承诺。</li><li>特里芬：美元流动性与黄金信心冲突。</li><li>资本管制推迟、金融开放加速崩溃。</li><li>关闭黄金窗口后，定锚问题交给滞胀课。</li><li>平价政治僵硬把特里芬裂缝攒成一次断裂，而不是一连串小调整。</li><li>出处：Triffin 1960；Eichengreen；Bordo。</li></ul>',6))])}const c=i(p,[["render",D]]);export{b as __pageData,c as default};
